-- PO-1C.2 — Certified Facial Hair & Skin Care Services inventory
-- Sources: current premium quiz banks for Chapters 12 and 13.
-- Deterministic even-coverage selection: 15 per chapter, 30 total.

insert into public.comprehensive_exam_questions (
 source_question_id,source_kind,source_chapter_id,domain,prompt,
 option_a,option_b,option_c,option_d,correct_option,explanation,
 content_version,provenance,status
) values
('qq-12-001','chapter_quiz','12','facial_hair_skin_care_services','What is the strongest reason to study Chapter 12 facial services?','To perform cosmetic facial services with consultation, sanitation, safe technique, and clear scope boundaries','To diagnose facial skin disorders before every service','To replace haircutting with facial treatment services','To provide medical therapy in the barbershop','a','Chapter 12 treats facial massage and treatments as professional cosmetic grooming services. Competence includes consultation, sanitation, technique, contraindications, comfort, and scope boundaries.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-004','chapter_quiz','12','facial_hair_skin_care_services','Which service may include a facial treatment as a finishing step according to the Chapter 12 material?','Hair coloring','Permanent waving','Nail enhancement','A shave','d','The retained Chapter 12 material identifies facials as a possible finishing service after a shave.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-007','chapter_quiz','12','facial_hair_skin_care_services','Which description best matches a vein?','A thick-walled vessel carrying blood under high pressure','A nerve carrying messages from the brain','A thin-walled vessel with valves that help blood return toward the heart','A fibrous tissue that contracts','c','The Chapter 12 anatomy material describes veins as thin-walled vessels with valves that help prevent backward flow.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-010','chapter_quiz','12','facial_hair_skin_care_services','Which muscle surrounds the eye socket and closes the eyelid?','Masseter','Orbicularis oculi','Buccinator','Trapezius','b','The orbicularis oculi surrounds the eye and closes the eyelid.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-014','chapter_quiz','12','facial_hair_skin_care_services','Which vessels return deoxygenated blood from the head, face, and neck toward the heart?','Common carotid arteries','Internal and external jugular veins','Superficial temporal arteries','Occipital arteries','b','The internal and external jugular veins are identified as the major venous return pathways from the head, face, and neck.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-017','chapter_quiz','12','facial_hair_skin_care_services','What is friction?','A focused rubbing movement performed with controlled pressure','A feather-light finishing stroke','A rapid trembling movement','A kneading movement','a','Friction is a rubbing movement performed with pressure over an underlying structure; facial use should remain controlled and appropriate to the area.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-020','chapter_quiz','12','facial_hair_skin_care_services','What does feathering-off mean?','Increasing pressure before ending the massage','Applying tapotement to the forehead','Removing product with a towel','Gradually reducing pressure as the hands leave the client''s face','d','Feathering-off is the gradual reduction of pressure when lifting the hands from the client''s face.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-023','chapter_quiz','12','facial_hair_skin_care_services','What is a facial steamer?','A device for injecting product into skin','A cabinet for storing dry towels','An electrical appliance that produces moist steam for facial service','A machine that mechanically exfoliates with crystals','c','A facial steamer is an electrical appliance that produces moist steam for a cosmetic facial service and must be used according to manufacturer directions.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-026','chapter_quiz','12','facial_hair_skin_care_services','Which description best matches high-frequency current in the Chapter 12 source?','A low-level direct current used only for muscle lifting','A high-rate oscillating electrical modality used in facial or scalp service','A mechanical exfoliation process','A moist-heat treatment','b','The source describes high-frequency current as a high-rate oscillating electrical modality used in facial and scalp service. Use must follow device guidance and scope.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-029','chapter_quiz','12','facial_hair_skin_care_services','How should a barber determine time, distance, intensity, or other settings for electrical facial equipment?','Use the specific device manufacturer directions, training, and applicable rules','Use one universal setting for every device','Use the longest setting the client tolerates','Copy the setting used by another client','a','C12-2 and C12-3 explicitly reject universal device settings. Product/device directions, training, contraindications, and applicable rules govern operation.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-032','chapter_quiz','12','facial_hair_skin_care_services','What is the best basis for selecting a facial cleanser?','The strongest formulation available','The client''s gender','The barber''s favorite brand','Observable skin needs, client sensitivities, the planned service, and manufacturer directions','d','The hardened lesson requires cosmetic product selection to follow client analysis, sensitivities, service needs, and product directions.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-036','chapter_quiz','12','facial_hair_skin_care_services','Which principle best describes the overall sequence of a basic facial service?','Begin with the strongest exfoliant, then consult afterward','Massage first, then decide whether the service is appropriate','Use every product category on every client','Consult and analyze first, then use appropriate cleansing, treatment/massage, mask or finishing steps, and moisturizer as the service plan requires','d','The hardened Chapter 12 lesson emphasizes consultation and analysis before selecting the sequence and products for the facial service.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-039','chapter_quiz','12','facial_hair_skin_care_services','At the end of a facial, how should finishing products be selected?','Use the same toner and moisturizer on every client','Choose whichever product has the strongest active ingredients','Base the choice on the client analysis, planned service, product directions, and client comfort','Skip product directions if the client has used the product before','c','Finishing products must fit the client analysis and service plan and be used according to manufacturer directions.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-042','chapter_quiz','12','facial_hair_skin_care_services','If blood or another body-fluid exposure occurs during a facial service, what should the barber do?','Finish the facial before addressing it','Stop the service and follow the applicable exposure-control procedure','Cover the area with product and continue','Use extra fragrance to mask contamination','b','The hardened infection-control section requires stopping the service and following the applicable exposure-control procedure when blood or body-fluid exposure occurs.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-12-045','chapter_quiz','12','facial_hair_skin_care_services','During a facial, the client reports burning and dizziness. What is the correct immediate response?','Stop the service and reassess safety before doing anything further','Continue at a lower intensity until the client adjusts','Add heat to improve comfort','Finish the current step before checking the client','a','Pain, burning, dizziness, or other unsafe responses require the barber to stop the service and reassess rather than continue the planned procedure.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-12-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-001','chapter_quiz','13','facial_hair_skin_care_services','Why is professional shaving an important barbering skill?','It replaces haircutting as the primary barber service','Controlled razor work, analysis, facial-hair design, and client care','It is required by one federal barbering law that applies identically in every state and school','It is performed only when a client has a skin disorder','b','Chapter 13 presents shaving as a core barbering skill that depends on observation, control, facial-feature awareness, and practice.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-004','chapter_quiz','13','facial_hair_skin_care_services','Why should barbers develop facial-hair design skill in addition to shaving technique?','It eliminates the need to learn haircutting','It is mandated by one national face-shape standard that every client must receive','Provide coordinated grooming based on client preference and growth','It allows the barber to diagnose facial asymmetry','c','Facial-hair design broadens grooming service and requires consultation, proportion, and growth-pattern awareness.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-007','chapter_quiz','13','facial_hair_skin_care_services','When should hot-towel preparation be avoided or modified?','Whenever the beard is coarse','Whenever the client had a haircut first','Compromised or highly heat-sensitive skin','Only when the beard is gray','c','The source cautions against hot towels on compromised or very sensitive skin.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-010','chapter_quiz','13','facial_hair_skin_care_services','A shaving nick produces visible blood. What should the barber do first?','Stop and follow the required blood-exposure procedure','Continue the shave and clean the area at the end','Cover the nick with lather and ignore it','Use a shared product applicator directly on the cut','a','A blood exposure requires an immediate pause and the applicable exposure-control procedure before continuing.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-014','chapter_quiz','13','facial_hair_skin_care_services','A client has inflamed ingrown-hair bumps and a history of keloid formation. What is the barber''s safest role?','Defer unsafe areas and refer rather than diagnose or treat','Diagnose folliculitis and prescribe an antibacterial product','Open the bumps before shaving','Shave very closely to remove trapped hairs','a','Chapter content can teach recognition of risk, but diagnosis and medical treatment are outside barbering scope.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-017','chapter_quiz','13','facial_hair_skin_care_services','What can visible beard-growth patterns tell the barber?','The client''s blood type','Whether the client has a product allergy and which aftershave should be prescribed','Direction changes, whorls, and how the beard lies','The exact age of each hair follicle','c','Growth patterns provide a visible guide to hair direction, hairline shape, and whorls or other directional changes.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-020','chapter_quiz','13','facial_hair_skin_care_services','What is the best way to use the 14-area shaving map?','Treat every area direction as identical on every client because the training map never changes','Use it only for against-grain close shaving','Ignore it whenever the beard is coarse','Use it systematically, but adjust to the client''s actual grain','d','The map organizes the service, but individual growth variations can require a different stroke.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-023','chapter_quiz','13','facial_hair_skin_care_services','Which three razor positions are primarily used for the 14-area facial shave?','Freehand, reverse backhand, and overhand','Backhand, overhand, and underhand','Reverse backhand only','Freehand, backhand, and reverse freehand','d','Facial shaving uses freehand, backhand, and reverse freehand; reverse backhand is mainly associated with neck and outline work.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-026','chapter_quiz','13','facial_hair_skin_care_services','Which description best fits the reverse-freehand stroke?','A downward outline stroke used only behind the ear','An upward, semi-arced point-leading glide used in designated areas','A horizontal sawing motion across the cheek','A flat-blade scraping stroke used without stretching because the upward direction provides enough control','b','Reverse freehand is an upward, semi-arced motion used in Areas 5, 10, 13, and 14.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-029','chapter_quiz','13','facial_hair_skin_care_services','In a freehand grip, what is the main goal of finger placement?','Hold the sharpened edge between the thumb and index finger','Stabilize the razor around the shank, pivot, tang, and handle','Grip only the handle and let the blade move freely','Press the blade flat against the palm','b','The source teaches a specific freehand grip to control the razor around the shank, pivot, tang, and handle.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-032','chapter_quiz','13','facial_hair_skin_care_services','What can happen if the skin is stretched too tightly?','The beard becomes permanently thinner','The razor automatically becomes dull','The lather stops working chemically','Irritation can increase','d','The source cautions against excessive skin tension because it can contribute to irritation.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-036','chapter_quiz','13','facial_hair_skin_care_services','Why are most shaving strokes kept relatively short, about 1 to 3 inches?','Because longer strokes are illegal','Because lather works for only three inches','To keep the blade close to the area being stretched and controlled','Because the razor must be closed after every stroke before the barber can stretch again','c','Shorter strokes keep the cutting area close to the support and stretch point.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-039','chapter_quiz','13','facial_hair_skin_care_services','Which statement best describes the first-time-over shave?','An against-grain close shave performed first to remove maximum beard growth in one pass','A dry razor pass done only on the neck','The main lathered pass, normally with the observed grain','A second pass used only for missed patches','c','The first-time-over is the primary pass and is generally performed with the grain.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-042','chapter_quiz','13','facial_hair_skin_care_services','A client requests an against-grain close shave. What should the barber evaluate before agreeing?','Only whether the client is willing to pay extra','Skin condition, growth pattern, ingrown-hair risk, training, and local rules','Only whether the beard is dark or gray','Nothing—against-grain shaving is always required for a professional result','b','Against-grain work can increase irritation and ingrown-hair risk and should be judged case by case.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-13-045','chapter_quiz','13','facial_hair_skin_care_services','What is a sound first step when trimming a beard toward a shorter target length?','Begin slightly longer than the final target and shorten gradually','Cut directly to the shortest possible length','Remove the natural cheek line before consultation so the final beard shape can be redrawn','Use the razor first on every area','a','Starting longer reduces the risk of removing more hair than intended and gives room to balance both sides.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-13-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active')
on conflict (source_question_id) do update set
 source_kind=excluded.source_kind,source_chapter_id=excluded.source_chapter_id,
 domain=excluded.domain,prompt=excluded.prompt,option_a=excluded.option_a,
 option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,
 correct_option=excluded.correct_option,explanation=excluded.explanation,
 content_version=excluded.content_version,provenance=excluded.provenance,
 status='active',updated_at=clock_timestamp();

with cfg as (
 select id from public.comprehensive_exam_configs where slug='nic-barber-theory' and version=1
),qs as (
 select id from public.comprehensive_exam_questions where source_question_id in ('qq-12-001','qq-12-004','qq-12-007','qq-12-010','qq-12-014','qq-12-017','qq-12-020','qq-12-023','qq-12-026','qq-12-029','qq-12-032','qq-12-036','qq-12-039','qq-12-042','qq-12-045','qq-13-001','qq-13-004','qq-13-007','qq-13-010','qq-13-014','qq-13-017','qq-13-020','qq-13-023','qq-13-026','qq-13-029','qq-13-032','qq-13-036','qq-13-039','qq-13-042','qq-13-045')
)
insert into public.comprehensive_exam_config_questions
 (config_id,question_id,scored_eligible,unscored_eligible,is_active)
select cfg.id,qs.id,true,true,true from cfg cross join qs
on conflict (config_id,question_id)
do update set scored_eligible=true,unscored_eligible=true,is_active=true;
